entries[209496] = { ["name"] = "Schreckensdorn", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nDämonenstahlbarren (6), Blut von Sargeras (8), Infernoschwefel (2)\nStellt einen Schreckensdorn her.\nBeute von:\nHelya\nZone:\nDer Seelenschlund (Heroisch)\n\nSchreckensdorn\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nBlut Artefaktrelikt\n\n+ 16 Gegenstands-Level\n45" }
