entries[209781] = { ["name"] = "Schattennova", ["text"] = "Rang 1/ 1 Artefakt Boni\nBenötigt Reißzähne des Verschlingers\nNach dem Einsatz von 'Schattenschlag' oder 'Fieser Trick' explodiert Ihr und fügt allen Gegnern in der Nähe (52.5% der Angriffskraft) Schattenschaden zu. Dieser Effekt wird ebenfalls ausgelöst, wenn Ihr 'Shurikensturm' einsetzt, während 'Schattentanz' aktiv ist.\n\nDieser Effekt kann nur einmal alle 5 Sek. auftreten.\n(5s Abklingzeit)" }
